export function normalizeFilenameKey(filename) {
  if (!filename) return null;
  const raw = String(filename).toLowerCase().trim();
  const name = raw.split('/').pop().split('\\').pop();
  const stem = name.replace(/\.[^/.]+$/, '');

  const candidates = [
    name,
    stem,
    stem.replace(/_/g, '-'),
    stem.replace(/-/g, '_'),
  ];
  for (const prefix of ['demo-', 'demo_', 'sample-', 'sample_']) {
    if (stem.startsWith(prefix)) {
      candidates.push(stem.slice(prefix.length));
    }
  }
  return candidates;
}

export function getGalleryDetection(filename) {
  const candidates = normalizeFilenameKey(filename);
  if (!candidates) return null;
  for (const key of candidates) {
    if (GALLERY_PRESET_CACHE[key]) {
      return GALLERY_PRESET_CACHE[key];
    }
  }
  return null;
}

export function getGalleryMetadata(filename) {
  const cached = getGalleryDetection(filename);
  if (!cached) return null;
  const srvId = cached.survey_id || (cached.image_id ? `SRV-${String(cached.image_id).toUpperCase()}` : 'SRV-DEMO');
  return {
    filename: cached.filename || filename,
    survey_id: srvId,
    vessel: cached.vessel || 'RV Samudra Ratna (NIOT)',
    start_coords: cached.start_coords || cached.coords || '13.0827, 80.2707',
    end_coords: cached.end_coords || '13.0855, 80.2735',
    heading_deg: cached.heading_deg ?? cached.heading ?? 184.2,
    depth_m: cached.depth_m ?? (cached.depth ? parseFloat(cached.depth) : 38.4),
    altitude_m: cached.altitude_m ?? cached.altitude ?? 8.5,
    timestamp: cached.timestamp || new Date().toISOString().replace('T', ' ').slice(0, 19),
    swath_width_m: cached.swath_width_m ?? 100.0,
    start_lat: cached.start_lat ?? 13.0827,
    start_lon: cached.start_lon ?? 80.2707,
    end_lat: cached.end_lat ?? 13.0855,
    end_lon: cached.end_lon ?? 80.2735,
  };
}
